PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS emails (id TEXT PRIMARY KEY, thread_id TEXT, mailbox TEXT NOT NULL, source TEXT NOT NULL, received_at TEXT NOT NULL, subject TEXT, sender TEXT, is_job_newsletter INTEGER NOT NULL DEFAULT 0, is_human_thread INTEGER NOT NULL DEFAULT 0, has_application_signal INTEGER NOT NULL DEFAULT 0, has_interview_signal INTEGER NOT NULL DEFAULT 0, expected_observation_count INTEGER NOT NULL DEFAULT 0, committed_at TEXT, content_hash TEXT NOT NULL, UNIQUE(mailbox,id));
CREATE TABLE IF NOT EXISTS email_parse_snapshots (email_id TEXT NOT NULL REFERENCES emails(id), parser_version TEXT NOT NULL, raw_html TEXT NOT NULL, parsed_links_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(email_id,parser_version));
CREATE TABLE IF NOT EXISTS observations (id TEXT PRIMARY KEY, email_id TEXT NOT NULL REFERENCES emails(id), ordinal INTEGER NOT NULL, source TEXT NOT NULL, link_kind TEXT NOT NULL CHECK(link_kind IN('listing','discovery')), url TEXT NOT NULL, title_hint TEXT, observed_at TEXT NOT NULL, UNIQUE(email_id,ordinal));
CREATE TABLE IF NOT EXISTS candidate_observations (observation_id TEXT PRIMARY KEY REFERENCES observations(id), parser_version TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS canonical_jobs (id TEXT PRIMARY KEY, source TEXT NOT NULL, external_id TEXT, canonical_url TEXT, title TEXT, company TEXT, location TEXT, engagement_type TEXT, first_seen_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, UNIQUE(source,external_id));
CREATE TABLE IF NOT EXISTS listing_versions (id TEXT PRIMARY KEY, canonical_job_id TEXT NOT NULL REFERENCES canonical_jobs(id), fetched_at TEXT NOT NULL, content_hash TEXT NOT NULL, full_description TEXT NOT NULL, salary_min REAL, hourly_min REAL, provider TEXT NOT NULL, UNIQUE(canonical_job_id,content_hash));
CREATE TABLE IF NOT EXISTS listing_renderings (listing_version_id TEXT PRIMARY KEY REFERENCES listing_versions(id), render_html TEXT NOT NULL, source_url TEXT NOT NULL, source_content_hash TEXT NOT NULL, fetched_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS authenticated_listing_checks (id TEXT PRIMARY KEY, canonical_job_id TEXT NOT NULL REFERENCES canonical_jobs(id), listing_version_id TEXT REFERENCES listing_versions(id), source_url TEXT NOT NULL, captured_at TEXT NOT NULL, availability TEXT NOT NULL CHECK(availability IN('open','closed','inaccessible')), capture_source TEXT NOT NULL CHECK(capture_source IN('external_chrome_bridge','unverified_dashboard_upload','public_server_fetch')), content_hash TEXT, created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS relabel_dashboard_capture AFTER INSERT ON authenticated_listing_checks WHEN NEW.capture_source='external_chrome_bridge' BEGIN UPDATE authenticated_listing_checks SET capture_source='unverified_dashboard_upload' WHERE id=NEW.id; END;
CREATE TABLE IF NOT EXISTS research_tasks (id TEXT PRIMARY KEY, observation_id TEXT REFERENCES observations(id), parent_task_id TEXT REFERENCES research_tasks(id), source TEXT NOT NULL, task_kind TEXT NOT NULL CHECK(task_kind IN('fetch_listing','walk_discovery')), url TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('pending','running','complete','login_required','blocked','incomplete_retry','not_a_listing')), attempts INTEGER NOT NULL DEFAULT 0, error_code TEXT, canonical_job_id TEXT REFERENCES canonical_jobs(id), completed_listing_version_id TEXT REFERENCES listing_versions(id), next_attempt_at TEXT, updated_at TEXT NOT NULL, superseded_by_task_id TEXT REFERENCES research_tasks(id));
CREATE TABLE IF NOT EXISTS research_task_observations (task_id TEXT NOT NULL REFERENCES research_tasks(id), observation_id TEXT NOT NULL REFERENCES observations(id), created_at TEXT NOT NULL, PRIMARY KEY(task_id,observation_id));
CREATE TABLE IF NOT EXISTS active_research_task_assignments (observation_id TEXT PRIMARY KEY REFERENCES observations(id), task_id TEXT NOT NULL REFERENCES research_tasks(id), assigned_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research_checkpoints (task_id TEXT PRIMARY KEY REFERENCES research_tasks(id), next_url TEXT, pages INTEGER NOT NULL DEFAULT 0, found_count INTEGER NOT NULL DEFAULT 0, state_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence (id TEXT PRIMARY KEY, canonical_job_id TEXT NOT NULL REFERENCES canonical_jobs(id), listing_version_id TEXT REFERENCES listing_versions(id), evidence_type TEXT NOT NULL, source_url TEXT NOT NULL, source_anchor TEXT, claim_text TEXT NOT NULL, fetched_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS arsenal_versions (version TEXT PRIMARY KEY, source_file_id TEXT NOT NULL, content_hash TEXT NOT NULL, imported_at TEXT NOT NULL, claim_count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS arsenal_claims (id TEXT NOT NULL, arsenal_version TEXT NOT NULL REFERENCES arsenal_versions(version), source_anchor TEXT NOT NULL, tags_json TEXT NOT NULL, claim_text TEXT NOT NULL, internal_only INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(id,arsenal_version));
CREATE TABLE IF NOT EXISTS assessments (id TEXT PRIMARY KEY, canonical_job_id TEXT NOT NULL REFERENCES canonical_jobs(id), profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL, arsenal_version TEXT NOT NULL, score REAL NOT NULL, band TEXT NOT NULL, explanation_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assessment_provenance (assessment_id TEXT PRIMARY KEY REFERENCES assessments(id), listing_version_id TEXT NOT NULL REFERENCES listing_versions(id), listing_content_hash TEXT NOT NULL, recorded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS saved_role_profiles (id TEXT NOT NULL, version INTEGER NOT NULL, name TEXT NOT NULL, profile_json TEXT NOT NULL, content_hash TEXT NOT NULL, created_at TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, status TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, counts_json TEXT NOT NULL DEFAULT '{}', arsenal_version TEXT, error_code TEXT);
CREATE TABLE IF NOT EXISTS cursors (scope TEXT PRIMARY KEY, cursor_value TEXT, overlap_from TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cleanup_outbox (id TEXT PRIMARY KEY, email_id TEXT NOT NULL REFERENCES emails(id), mode TEXT NOT NULL CHECK(mode='preview'), status TEXT NOT NULL CHECK(status IN('candidate','ineligible','previewed')), eligibility_reason TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, verified_at TEXT);
CREATE TABLE IF NOT EXISTS audit (id TEXT PRIMARY KEY, occurred_at TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, detail_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS job_requirements (id TEXT PRIMARY KEY, canonical_job_id TEXT NOT NULL REFERENCES canonical_jobs(id), listing_version_id TEXT NOT NULL REFERENCES listing_versions(id), requirement_kind TEXT NOT NULL CHECK(requirement_kind IN('must_have','nice_to_have','implied')), requirement_text TEXT NOT NULL, source_anchor TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS company_dossiers (id TEXT PRIMARY KEY, canonical_job_id TEXT REFERENCES canonical_jobs(id), company TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('draft','researching','evidence_complete','reviewed')), summary TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS company_dossier_sources (id TEXT PRIMARY KEY, dossier_id TEXT NOT NULL REFERENCES company_dossiers(id), source_url TEXT NOT NULL, source_title TEXT, claim_text TEXT NOT NULL, fetched_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fit_reviews (id TEXT PRIMARY KEY, canonical_job_id TEXT NOT NULL REFERENCES canonical_jobs(id), listing_version_id TEXT NOT NULL REFERENCES listing_versions(id), assessment_id TEXT REFERENCES assessments(id), verdict TEXT NOT NULL CHECK(verdict IN('pursue','pursue_with_fixes','skip','manual_review')), odds_label TEXT, gaps_json TEXT NOT NULL, quick_fixes_json TEXT NOT NULL, must_have_veto INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL CHECK(status IN('draft','final')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS application_packages (id TEXT PRIMARY KEY, canonical_job_id TEXT NOT NULL REFERENCES canonical_jobs(id), listing_version_id TEXT NOT NULL REFERENCES listing_versions(id), arsenal_version TEXT NOT NULL REFERENCES arsenal_versions(version), status TEXT NOT NULL CHECK(status IN('writer_draft','writer_review','critic_review','chris_review','approved','rejected')), revision INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS application_artifacts (id TEXT PRIMARY KEY, package_id TEXT NOT NULL REFERENCES application_packages(id), artifact_type TEXT NOT NULL CHECK(artifact_type IN('tailored_resume','pain_letter','cover_letter','outreach')), drive_file_id TEXT, content_hash TEXT NOT NULL, evidence_map_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('draft','reviewed','approved')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS artifact_readback_claims (artifact_id TEXT PRIMARY KEY REFERENCES application_artifacts(id), drive_file_id TEXT NOT NULL, content_hash TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size>0), drive_modified_time TEXT NOT NULL, status TEXT NOT NULL CHECK(status='pending_external_verification'), recorded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS artifact_verifications (artifact_id TEXT PRIMARY KEY REFERENCES application_artifacts(id), drive_file_id TEXT NOT NULL, content_hash TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size>0), drive_modified_time TEXT NOT NULL, verification_source TEXT NOT NULL CHECK(verification_source='trusted_connector_receipt'), receipt_hash TEXT NOT NULL UNIQUE CHECK(length(receipt_hash)=64), verified_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS package_reviews (id TEXT PRIMARY KEY, package_id TEXT NOT NULL REFERENCES application_packages(id), package_revision INTEGER NOT NULL, reviewer_role TEXT NOT NULL CHECK(reviewer_role IN('writer','critic','chris')), decision TEXT NOT NULL CHECK(decision IN('request_changes','approve','reject')), notes TEXT, created_at TEXT NOT NULL, UNIQUE(package_id,package_revision));
CREATE TABLE IF NOT EXISTS pipeline_items (id TEXT PRIMARY KEY, canonical_job_id TEXT NOT NULL REFERENCES canonical_jobs(id), stage TEXT NOT NULL CHECK(stage IN('target','considering','package_draft','chris_review','approved_to_send','applied','conversation','interviewing','offer','closed')), approved_package_id TEXT REFERENCES application_packages(id), approved_package_revision INTEGER, approved_listing_version_id TEXT REFERENCES listing_versions(id), approval_check_id TEXT REFERENCES authenticated_listing_checks(id), next_action TEXT, owner TEXT, due_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS guard_approved_to_send_insert BEFORE INSERT ON pipeline_items WHEN NEW.stage='approved_to_send' BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM application_packages p JOIN authenticated_listing_checks c ON c.id=NEW.approval_check_id WHERE p.id=NEW.approved_package_id AND p.status='approved' AND p.revision=NEW.approved_package_revision AND p.listing_version_id=NEW.approved_listing_version_id AND c.canonical_job_id=NEW.canonical_job_id AND c.listing_version_id=NEW.approved_listing_version_id AND c.availability='open' AND c.capture_source='public_server_fetch' AND c.captured_at>=strftime('%Y-%m-%dT%H:%M:%fZ','now','-15 minutes') AND NOT EXISTS(SELECT 1 FROM application_artifacts a LEFT JOIN artifact_verifications v ON v.artifact_id=a.id WHERE a.package_id=p.id AND (a.status<>'approved' OR a.drive_file_id IS NULL OR v.artifact_id IS NULL OR v.drive_file_id<>a.drive_file_id OR LOWER(v.content_hash)<>LOWER(a.content_hash)))) THEN RAISE(ABORT,'approved_to_send_guard_failed') END; END;
CREATE TRIGGER IF NOT EXISTS guard_approved_to_send_update BEFORE UPDATE OF stage,approved_package_id,approved_package_revision,approved_listing_version_id,approval_check_id ON pipeline_items WHEN NEW.stage='approved_to_send' BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM application_packages p JOIN authenticated_listing_checks c ON c.id=NEW.approval_check_id WHERE p.id=NEW.approved_package_id AND p.status='approved' AND p.revision=NEW.approved_package_revision AND p.listing_version_id=NEW.approved_listing_version_id AND c.canonical_job_id=NEW.canonical_job_id AND c.listing_version_id=NEW.approved_listing_version_id AND c.availability='open' AND c.capture_source='public_server_fetch' AND c.captured_at>=strftime('%Y-%m-%dT%H:%M:%fZ','now','-15 minutes') AND NOT EXISTS(SELECT 1 FROM application_artifacts a LEFT JOIN artifact_verifications v ON v.artifact_id=a.id WHERE a.package_id=p.id AND (a.status<>'approved' OR a.drive_file_id IS NULL OR v.artifact_id IS NULL OR v.drive_file_id<>a.drive_file_id OR LOWER(v.content_hash)<>LOWER(a.content_hash)))) THEN RAISE(ABORT,'approved_to_send_guard_failed') END; END;
CREATE TABLE IF NOT EXISTS interviews (id TEXT PRIMARY KEY, pipeline_item_id TEXT NOT NULL REFERENCES pipeline_items(id), scheduled_at TEXT, status TEXT NOT NULL CHECK(status IN('planned','scheduled','complete','cancelled')), next_action TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS interviewer_dossiers (id TEXT PRIMARY KEY, interview_id TEXT NOT NULL REFERENCES interviews(id), interviewer_name TEXT NOT NULL, company TEXT, drive_file_id TEXT, status TEXT NOT NULL CHECK(status IN('draft','evidence_complete','reviewed')), sources_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS interview_records (id TEXT PRIMARY KEY, interview_id TEXT NOT NULL REFERENCES interviews(id), record_kind TEXT NOT NULL CHECK(record_kind IN('recruiter_prep','psych_brief','practice','debrief')), content_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('draft','reviewed','chris_approved')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS coach_plans (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, profile_version INTEGER NOT NULL, period_start TEXT NOT NULL, commitments_json TEXT NOT NULL, actuals_json TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL CHECK(status IN('draft','active','reviewed','closed')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS private_doc_sessions (id TEXT PRIMARY KEY, occurred_at TEXT NOT NULL, private_notes TEXT NOT NULL, access_scope TEXT NOT NULL DEFAULT 'private_only' CHECK(access_scope='private_only'), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approved_doc_insights (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES private_doc_sessions(id), approved_text TEXT NOT NULL, approved_at TEXT NOT NULL, destination TEXT NOT NULL, UNIQUE(session_id,approved_text,destination));
CREATE TABLE IF NOT EXISTS ai_budget_months (month_utc TEXT PRIMARY KEY, limit_microusd INTEGER NOT NULL CHECK(limit_microusd=1000000), reserved_microusd INTEGER NOT NULL DEFAULT 0 CHECK(reserved_microusd>=0), spent_microusd INTEGER NOT NULL DEFAULT 0 CHECK(spent_microusd>=0), updated_at TEXT NOT NULL, CHECK(reserved_microusd+spent_microusd<=limit_microusd));
CREATE TABLE IF NOT EXISTS ai_requests (id TEXT PRIMARY KEY, month_utc TEXT NOT NULL REFERENCES ai_budget_months(month_utc), model TEXT NOT NULL, purpose TEXT NOT NULL CHECK(purpose IN('tailored_resume','pain_letter','cover_letter','outreach','company_brief','interview_prep','coach_plan')), canonical_job_id TEXT NOT NULL REFERENCES canonical_jobs(id), max_input_tokens INTEGER NOT NULL CHECK(max_input_tokens>0), max_output_tokens INTEGER NOT NULL CHECK(max_output_tokens>0 AND max_output_tokens<=900), reserved_microusd INTEGER NOT NULL CHECK(reserved_microusd>0), actual_input_tokens INTEGER, actual_output_tokens INTEGER, charged_microusd INTEGER, status TEXT NOT NULL CHECK(status IN('reserved','complete','failed','rejected')), created_at TEXT NOT NULL, completed_at TEXT, error_code TEXT, response_hash TEXT);
CREATE TRIGGER IF NOT EXISTS reserve_ai_request_budget AFTER INSERT ON ai_requests WHEN NEW.status='reserved' BEGIN UPDATE ai_budget_months SET reserved_microusd=reserved_microusd+NEW.reserved_microusd,updated_at=NEW.created_at WHERE month_utc=NEW.month_utc AND spent_microusd+reserved_microusd+NEW.reserved_microusd<=limit_microusd; SELECT CASE WHEN changes()!=1 THEN RAISE(ABORT,'ai_monthly_budget_exhausted') END; END;
CREATE TRIGGER IF NOT EXISTS settle_ai_request_budget AFTER UPDATE OF status ON ai_requests WHEN OLD.status='reserved' AND NEW.status<>'reserved' BEGIN UPDATE ai_budget_months SET reserved_microusd=reserved_microusd-OLD.reserved_microusd, spent_microusd=spent_microusd+NEW.charged_microusd, updated_at=NEW.completed_at WHERE month_utc=OLD.month_utc AND reserved_microusd>=OLD.reserved_microusd AND NEW.charged_microusd=OLD.reserved_microusd AND spent_microusd+reserved_microusd<=limit_microusd; SELECT CASE WHEN changes()!=1 THEN RAISE(ABORT,'ai_budget_settlement_invariant') END; END;
CREATE TABLE IF NOT EXISTS ai_drafts (id TEXT PRIMARY KEY, ai_request_id TEXT NOT NULL UNIQUE REFERENCES ai_requests(id), canonical_job_id TEXT NOT NULL REFERENCES canonical_jobs(id), artifact_type TEXT NOT NULL CHECK(artifact_type IN('tailored_resume','pain_letter','cover_letter','outreach','company_brief','interview_prep','coach_plan')), arsenal_version TEXT NOT NULL REFERENCES arsenal_versions(version), listing_version_id TEXT NOT NULL REFERENCES listing_versions(id), content TEXT NOT NULL, content_hash TEXT NOT NULL, evidence_map_json TEXT NOT NULL, warnings_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status='draft_unreviewed'), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_tasks_status ON research_tasks(status,updated_at); CREATE INDEX IF NOT EXISTS idx_task_observations_observation ON research_task_observations(observation_id,task_id); CREATE INDEX IF NOT EXISTS idx_obs_email ON observations(email_id); CREATE INDEX IF NOT EXISTS idx_evidence_job ON evidence(canonical_job_id);
CREATE INDEX IF NOT EXISTS idx_authenticated_checks_job ON authenticated_listing_checks(canonical_job_id,captured_at DESC);
CREATE INDEX IF NOT EXISTS idx_requirements_job ON job_requirements(canonical_job_id,listing_version_id); CREATE INDEX IF NOT EXISTS idx_pipeline_stage ON pipeline_items(stage,updated_at); CREATE INDEX IF NOT EXISTS idx_packages_job ON application_packages(canonical_job_id,status); CREATE INDEX IF NOT EXISTS idx_interviews_pipeline ON interviews(pipeline_item_id,status); CREATE INDEX IF NOT EXISTS idx_assessment_listing ON assessment_provenance(listing_version_id); CREATE INDEX IF NOT EXISTS idx_ai_requests_month ON ai_requests(month_utc,status); CREATE INDEX IF NOT EXISTS idx_ai_drafts_job ON ai_drafts(canonical_job_id,created_at);
-- Secrets and OAuth tokens are intentionally absent. Use encrypted platform secrets and a token broker; bind grants to EXPECTED_MAILBOX with state + PKCE.

